import {report} from './report.js';import {effectiveCustomerId} from './customers.js';import {unionArea} from './geometry.js';
export function areaTables(doc,scope='all'){const {floors,total}=report(doc,scope);return {floors:floors.map(f=>[f.label,f.footprint,f.reserved,Math.max(0,f.footprint-f.reserved),f.sectionArea,f.unsectioned,f.used,f.whitespace]),total:['Total',total.footprint,total.reserved,Math.max(0,total.footprint-total.reserved),total.sectionArea,total.unsectioned,total.used,total.whitespace],sections:floors.flatMap(f=>f.sections.map(s=>[f.label,s.name,s.rackPlacement===false?'Reserved non-storage':'Storage-enabled',s.stats.total,s.stats.used,s.stats.assigned,s.stats.unassigned,s.stats.free]))};}
export function customerTables(doc,scope='all'){const {floors}=report(doc,scope),customers=doc.customers||[],name=id=>customers.find(c=>c.id===id)?.name||'Unassigned',groups=new Map(customers.map(c=>[c.id,{id:c.id,name:c.name,externalId:c.externalId||'',description:c.description||'',sectionArea:0,reservedArea:0,rackArea:0,racks:0,pallets:0}]));groups.set(null,{id:null,name:'Unassigned',externalId:'',description:'No customer assigned',sectionArea:0,reservedArea:0,rackArea:0,racks:0,pallets:0});const sections=[],rackGroups=new Map();for(const f of floors){for(const [id,g]of groups){g.sectionArea+=unionArea(f.sections.filter(s=>(s.customerId??null)===id));g.reservedArea+=unionArea(f.sections.filter(s=>(s.customerId??null)===id&&s.rackPlacement===false));}for(const s of f.sections)sections.push([name(s.customerId??null),f.label,s.name,s.rackPlacement===false?'Reserved non-storage':'Storage-enabled',s.stats.total]);for(const r of f.racks){const id=effectiveCustomerId(f,r),g=groups.get(id??null),t=doc.rackTypes.find(t=>t.id===r.typeId),s=f.sections.find(s=>s.id===r.sectionId),mode=Object.hasOwn(r,'customerId')?(r.customerId?'Rack override':'Explicitly unassigned'):'Section default',key=JSON.stringify([id,f.id,r.sectionId,mode]);if(!g||!t)continue;const footprint=t.length*t.width;g.rackArea+=footprint;g.racks++;g.pallets+=t.pallets;if(!rackGroups.has(key))rackGroups.set(key,[name(id),f.label,s?.name||'',mode,0,0,0]);const row=rackGroups.get(key);row[4]++;row[5]+=footprint;row[6]+=t.pallets;}}return {summary:[...groups.values()].map(g=>[g.name,g.externalId,g.sectionArea,g.reservedArea,g.rackArea,g.racks,g.pallets]),sections,racks:[...rackGroups.values()]};}
